import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import './Thread.css';

const ThreadDetail = () => {
    const { id } = useParams();
    const [threadDetail, setThreadDetail] = useState(null);

    useEffect(() => {
        fetch(`/data/threadDetail/threadDetail-${id}.json`) // Charger dynamiquement en fonction de l'ID du thread
            .then(response => response.json())
            .then(data => setThreadDetail(data))
            .catch(error => console.error('Error fetching thread detail:', error));
    }, [id]);

    if (!threadDetail) {
        return <p>Loading thread details...</p>;
    }

    return (
        <div className="thread-detail">
            <h2>{threadDetail.title}</h2>
            <p><em>by {threadDetail.author} on {threadDetail.date}</em></p>
            <div className="posts">
                <h3>Posts</h3>
                {threadDetail.posts.length > 0 ? (
                    <ul>
                        {threadDetail.posts.map(post => (
                            <li key={post.postId} className="post">
                                <img src={post.avatar} alt={`${post.author}'s avatar`} className="avatar" />
                                <div>
                                    <p><strong>{post.author}</strong> on {post.date}</p>
                                    <p>{post.content}</p>
                                </div>
                            </li>
                        ))}
                    </ul>
                ) : (
                    <p>No posts available</p>
                )}
            </div>
        </div>
    );
};

export default ThreadDetail;
